{
  "questions": [
    {
      "text": "お宮参りの時期はいつ頃を予定していますか？",
      "options": [
        "生後1か月前後（12月上旬）",
        "生後100日前後・暖かくなってから（春頃）"
      ]
    },
    {
      "text": "当日はどなたが参加する予定ですか？",
      "options": [
        "赤ちゃんと両親のみ",
        "祖父母も一緒に参加"
      ]
    },
    {
      "text": "写真撮影やご祈祷、会食はどのように行いますか？",
      "options": [
        "ご祈祷と参拝のみシンプルに行う",
        "ご祈祷に加えて写真館での撮影や会食も行う"
      ]
    }
  ]
}
